import {KEY,validateBoard,sanitizeProgress,completed,migrateAnswerImages} from './state.js';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
let state,selected,stage='question',undo=[],draft;
const roundIndex=(value,board)=>Number.isInteger(Number(value))?Math.max(0,Math.min(Number(value),board.rounds.length-1)):0;
const defaults=validateBoard(await(await fetch('quiz.json')).json());
try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw){validateBoard(raw.board);state={board:raw.board,done:sanitizeProgress(raw.board,raw.done),round:roundIndex(raw.round,raw.board)};}}catch{$('notice').textContent='Saved data could not be read. The original board has been loaded.';}
state??={board:defaults,done:{},round:0};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));$('saved').textContent='● Saved on this browser';return true;}catch{$('saved').textContent='⚠ Progress is not saved';$('notice').textContent='Browser storage is unavailable or full. Download a backup before leaving.';return false;}}
function render(){
 if(migrateAnswerImages(state.board,defaults))persist();
 const r=state.board.rounds[state.round],qs=r.categories.flatMap(c=>c.questions),count=qs.filter(q=>state.done[q.id]).length;
 document.title=state.board.title+' — Quiz Night';$('quiz-title').textContent=state.board.title;$('subtitle').textContent=state.board.subtitle||'Choose a category and point value. Your progress saves on this browser.';$('done-count').textContent=`${count} / ${qs.length}`;$('progress').style.width=(qs.length?count/qs.length*100:0)+'%';$('remaining').textContent=count===qs.length?'Round complete. Nicely played.':`${qs.length-count} questions still in play · ${qs.filter(q=>!state.done[q.id]).reduce((a,q)=>a+q.points,0)} points available`;
 $('rounds').replaceChildren(...state.board.rounds.map((r,i)=>{const b=el('button',r.name,i===state.round?'active':'');b.setAttribute('aria-pressed',i===state.round);b.onclick=()=>{state.round=i;persist();render();};return b;}));
 $('board').style.setProperty('--cols',r.categories.length);$('board').replaceChildren(...r.categories.map((c,i)=>{const col=el('div',undefined,'category'),head=el('div',undefined,'category-head');head.append(el('span',String(i+1).padStart(2,'0')),el('div',c.name));col.append(head);for(const q of c.questions){const used=!!state.done[q.id],b=el('button',undefined,'tile'+(used?' complete':''));b.append(el('b',q.points));if(used)b.append(el('small','COMPLETE'));b.setAttribute('aria-label',`${c.name}, ${q.points} points${used?', complete, reopen to review':''}`);b.onclick=()=>openQuestion(c,q);col.append(b);}return col;}));$('undo').disabled=!undo.length;
}
function openQuestion(c,q){selected={c,q};stage='question';renderQuestion();$('question-dialog').showModal();}
function button(text,action,cls){const b=el('button',text,cls);b.onclick=action;return b;}
function renderQuestion(){
 const {c,q}=selected;$('question-label').textContent=`${c.name} / ${q.points} POINTS`;$('stage-pill').textContent=stage;$('question-status').textContent=state.done[q.id]?'This question is complete.':'Not completed yet';const body=$('question-body');body.replaceChildren();
 if(stage==='safety'){body.append(el('div','Safety slide','safety'),el('p','Ready for the answer?\nMake sure everyone has locked in their guess.'));}
 else{if(stage==='question')body.append(el('h2',q.prompt));else if(q.answer)body.append(el('h2',q.answer));const src=stage==='question'?q.questionImage:q.answerImage;if(src){const img=el('img');img.src=src;img.alt=stage==='question'?'Visual clue':'Answer panel';img.className=stage==='answer'?'answer':'';img.onerror=()=>{img.remove();body.append(el('p','This image could not be loaded. Check the image URL in Manage board.'));};body.append(img);}else if(stage==='answer'&&!q.answer)body.append(el('p','No answer added yet. Add one in Manage board.'));}
 const actions=$('question-actions');actions.replaceChildren();
 if(stage==='question')actions.append(button('Lock in guesses →',()=>{stage='safety';renderQuestion();},'primary'));
 if(stage==='safety')actions.append(button('← Question',()=>{stage='question';renderQuestion();}),button('Reveal answer →',()=>{stage='answer';renderQuestion();},'primary'));
 if(stage==='answer')actions.append(button('← Question',()=>{stage='question';renderQuestion();}),button(state.done[q.id]?'Mark available':'Finish & return to board ✓',()=>{const old=!!state.done[q.id];undo.push({id:q.id,value:old});state=completed(state,q.id,!old);persist();render();$('question-dialog').close();},'primary'));
}
$('back').onclick=()=>$('question-dialog').close();
$('question-dialog').addEventListener('close',()=>{selected=null;});
$('undo').onclick=()=>{const last=undo.pop();if(last){state=completed(state,last.id,last.value);persist();render();}};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('notice').textContent='Full screen is unavailable in this browser. Use your browser’s full-screen command.';}};
function field(parent,label,value,change,type='text'){const l=el('label',label),input=el(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.value=value??'';input.oninput=()=>change(type==='number'?Number(input.value):input.value);l.append(input);parent.append(l);return l;}
function editor(){
 $('editor').replaceChildren();for(const r of draft.rounds){const block=el('div');field(block,'Round name',r.name,v=>r.name=v);for(const c of r.categories){const det=el('details');det.append(el('summary',`${c.name} · ${c.questions.length} questions`));field(det,'Category name',c.name,v=>c.name=v);for(const q of c.questions){const detail=el('details');detail.append(el('summary',`${q.points} points · ${q.prompt.slice(0,55)}`));const grid=el('div',undefined,'question-edit');field(grid,'Points',q.points,v=>q.points=v,'number');field(grid,'Question',q.prompt,v=>q.prompt=v,'textarea');field(grid,'Question image URL',q.questionImage,v=>q.questionImage=v).className='wide';field(grid,'Answer',q.answer,v=>q.answer=v,'textarea').className='wide';field(grid,'Answer image URL',q.answerImage,v=>q.answerImage=v).className='wide';detail.append(grid,button('Remove question',()=>{c.questions=c.questions.filter(x=>x!==q);editor();},'quiet'));det.append(detail);}det.append(button('+ Question',()=>{c.questions.push({id:crypto.randomUUID(),points:(c.questions.length+1)*10,prompt:'Your question',answer:'Your answer',questionImage:'',answerImage:''});editor();},'quiet'),button('Remove category',()=>{if(r.categories.length===1){$('settings-error').textContent='Keep at least one category in each round.';return;}r.categories=r.categories.filter(x=>x!==c);editor();},'quiet'));block.append(det);}$('editor').append(block);}
}
$('settings').onclick=()=>{draft=structuredClone(state.board);$('edit-title').value=draft.title;$('edit-subtitle').value=draft.subtitle;$('settings-error').textContent='';$('reset-confirm').hidden=true;editor();$('settings-dialog').showModal();};
$('add-category').onclick=()=>{const r=draft.rounds[state.round];if(r.categories.length>=8){$('settings-error').textContent='A round can have up to eight categories.';return;}r.categories.push({id:crypto.randomUUID(),name:'New category',questions:[]});editor();};
$('save-settings').onclick=()=>{try{draft.title=$('edit-title').value;draft.subtitle=$('edit-subtitle').value;validateBoard(draft);state.board=structuredClone(draft);state.done=sanitizeProgress(state.board,state.done);undo=[];persist();render();$('settings-dialog').close();}catch(e){$('settings-error').textContent=e.message;}};
$('reset').onclick=()=>$('reset-confirm').hidden=false;$('cancel-reset').onclick=()=>$('reset-confirm').hidden=true;
$('confirm-reset').onclick=()=>{state.done={};undo=[];persist();render();$('reset-confirm').hidden=true;$('settings-error').textContent='Progress cleared. All questions are available.';};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({...state,format:'quiz-night-backup',exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='quiz-night-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const file=$('file').files[0];if(!file)return;if(file.size>2000000)throw Error('Backup must be under 2 MB.');const raw=JSON.parse(await file.text());validateBoard(raw.board);state={board:raw.board,done:sanitizeProgress(raw.board,raw.done),round:roundIndex(raw.round,raw.board)};undo=[];persist();render();$('settings-dialog').close();$('notice').textContent='Backup restored.';}catch(e){$('settings-error').textContent='Could not restore: '+e.message;}finally{$('file').value='';}};
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const raw=JSON.parse(e.newValue);validateBoard(raw.board);state={board:raw.board,done:sanitizeProgress(raw.board,raw.done),round:roundIndex(raw.round,raw.board)};undo=[];if($('question-dialog').open)$('question-dialog').close();if($('settings-dialog').open)$('settings-dialog').close();render();$('notice').textContent='Progress updated from another tab.';}catch{}});
render();
